window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5ae260ffc63d2a7c"]={"versions": [{"id": "FIG-5ae260ffc63d2a7c", "releases": ["R2.1.20", "R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Rollen- und Artefakt-Flussdiagramm (Modellierung von Artefakten und Entwickleraktivitäten im Integrationsprozess) im Kontext des AUTOSAR Basic Software Schedulers (SchM) innerhalb der AUTOSAR Classic Platform. Das Diagramm zeigt die Interaktion der Rolle des Integrators/Implementierers des BSW Schedulers mit Eingangs- und Ausgangsartefakten (Header, Quelltexte, Objektdateien, XML-Beschreibungen und Executables).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteur</strong>:\n<ul class=\"fig-list\"><li><code>Integrator (Implementor of BSW Scheduler)</code>: Rolle/Entwickler, der SchM implementiert und das Gesamtsystem baut.\n</li></ul>\n</li><li><strong>Eingangsartefakte (Zulieferung BSW-Module)</strong>:\n<ul class=\"fig-list\"><li><code>&lt;ModulePrefix&gt;</code> (<code>.c</code>-Dateien, gestapelt): Quellcode des BSW-Moduls.\n</li><li><code>&lt;ModulePrefix&gt;_cfg</code> (<code>.h</code>-Dateien): Modulspezifische Konfigurations-Header.\n</li><li><code>&lt;ModulePrefix&gt;</code> (<code>.obj</code>): Vorkompilierte Objektdatei des BSW-Moduls.\n</li><li><code>&lt;ModulePrefix&gt;_Description</code> (<code>.XML</code>): Modulbeschreibungsdatei.\n</li></ul>\n</li><li><strong>SchM-Artefakte</strong>:\n<ul class=\"fig-list\"><li><code>SchM</code> (<code>.c</code>): Implementierung des BSW-Schedulers.\n</li><li><code>SchM_cfg</code> (<code>.h</code>): Konfigurations-Header des SchM.\n</li><li><code>SchM_&lt;ModulePrefix&gt;</code> (<code>.h</code>): Modulspezifischer Scheduler-Header für Standardaufrufe.\n</li><li><code>SchM_&lt;ModulePrefix&gt;_*(optimized)</code> (<code>.h</code>): Modulspezifischer optimierter Scheduler-Header.\n</li></ul>\n</li><li><strong>Zielartefakt</strong>:\n<ul class=\"fig-list\"><li><code>BasicSoftware</code> (<code>.exe</code>): Kompiliertes/gelinktes Gesamtsystem der Basissoftware.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Stereotypen</strong>:\n<ul class=\"fig-list\"><li><code>«deliveredTo»</code>: Modul-Artefakte (<code>.obj</code>, <code>.XML</code>) werden an den Integrator geliefert.\n</li><li><code>«refersTo»</code>: Integrator bzw. Executable referenziert Artefakte (<code>.obj</code>, <code>.c</code>, <code>.XML</code>).\n</li><li><code>«implements»</code>: Integrator implementiert <code>SchM</code> (<code>.c</code>).\n</li><li><code>«includes»</code>: <code>SchM</code> (<code>.c</code>) bindet <code>SchM_cfg</code> (<code>.h</code>) ein.\n</li><li><code>«generates»</code>: Integrator generiert bzw. baut <code>BasicSoftware</code> (<code>.exe</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Zulieferung</strong>: Der BSW-Modullieferant liefert Quellcode bzw. vorkompilierte Binaries (<code>.obj</code>), Konfigurations-Header (<code>&lt;ModulePrefix&gt;_cfg.h</code>) und XML-Beschreibungen (<code>&lt;ModulePrefix&gt;_Description.XML</code>) an den Integrator (<code>«deliveredTo»</code>).\n</li><li><strong>Implementierung</strong>: Der Integrator implementiert den BSW-Scheduler (<code>SchM.c</code>) unter Bezugnahme auf die Modulbeschreibungen und BSW-Artefakte.\n</li><li><strong>Inklusion &amp; Schnittstellen</strong>: <code>SchM.c</code> inkludiert die Konfiguration <code>SchM_cfg.h</code>; modulspezifische Header (<code>SchM_&lt;ModulePrefix&gt;.h</code>, optimierte Varianten) stellen die Scheduler-Schnittstellen für die BSW-Module bereit.\n</li><li><strong>Erzeugung</strong>: Der Integrator erzeugt über Link- und Build-Schritte aus den Modulobjekten und SchM-Quellen das lauffähige Binary <code>BasicSoftware.exe</code> (<code>«generates»</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild verdeutlicht die Integratorperspektive auf die BSW-Scheduler-Generierung und -Kompilierung. In frühen AUTOSAR-Releases (R2.1/R3.0) ist der SchM häufig noch manuell oder halbautomatisch durch den Integrator implementiert bzw. konfiguriert worden. Entwickler müssen sicherstellen, dass die BSW-Modul-Header (<code>&lt;ModulePrefix&gt;_cfg.h</code>) und SchM-Header (<code>SchM_&lt;ModulePrefix&gt;.h</code>) konsistent eingebunden werden und XML-Beschreibungen mit den Binärartefakten (<code>.obj</code>) der Module übereinstimmen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9909d30d87148705", "releases": ["R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Rollen- und Artefakt-Flussdiagramm (Modellierung von Artefakten und Entwickleraktivitäten im Integrationsprozess) im Kontext des AUTOSAR Basic Software Schedulers (SchM) innerhalb der AUTOSAR Classic Platform. Das Diagramm zeigt die Interaktion der Rolle des Integrators/Implementierers des BSW Schedulers mit Eingangs- und Ausgangsartefakten (Header, Quelltexte, Objektdateien, XML-Beschreibungen und Executables).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteur</strong>:\n<ul class=\"fig-list\"><li><code>Integrator (Implementor of BSW Scheduler)</code>: Rolle/Entwickler, der SchM implementiert und das Gesamtsystem baut.\n</li></ul>\n</li><li><strong>Eingangsartefakte (Zulieferung BSW-Module)</strong>:\n<ul class=\"fig-list\"><li><code>&lt;ModulePrefix&gt;</code> (<code>.c</code>-Dateien, gestapelt): Quellcode des BSW-Moduls.\n</li><li><code>&lt;ModulePrefix&gt;_cfg</code> (<code>.h</code>-Dateien): Modulspezifische Konfigurations-Header.\n</li><li><code>&lt;ModulePrefix&gt;</code> (<code>.obj</code>): Vorkompilierte Objektdatei des BSW-Moduls.\n</li><li><code>&lt;ModulePrefix&gt;_Description</code> (<code>.XML</code>): Modulbeschreibungsdatei.\n</li></ul>\n</li><li><strong>SchM-Artefakte</strong>:\n<ul class=\"fig-list\"><li><code>SchM</code> (<code>.c</code>): Implementierung des BSW-Schedulers.\n</li><li><code>SchM_cfg</code> (<code>.h</code>): Konfigurations-Header des SchM.\n</li><li><code>SchM_&lt;ModulePrefix&gt;</code> (<code>.h</code>): Modulspezifischer Scheduler-Header für Standardaufrufe.\n</li><li><code>SchM_&lt;ModulePrefix&gt;_*(optimized)</code> (<code>.h</code>): Modulspezifischer optimierter Scheduler-Header.\n</li></ul>\n</li><li><strong>Zielartefakt</strong>:\n<ul class=\"fig-list\"><li><code>BasicSoftware</code> (<code>.exe</code>): Kompiliertes/gelinktes Gesamtsystem der Basissoftware.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Stereotypen</strong>:\n<ul class=\"fig-list\"><li><code>«deliveredTo»</code>: Modul-Artefakte (<code>.obj</code>, <code>.XML</code>) werden an den Integrator geliefert.\n</li><li><code>«refersTo»</code>: Integrator bzw. Executable referenziert Artefakte (<code>.obj</code>, <code>.c</code>, <code>.XML</code>).\n</li><li><code>«implements»</code>: Integrator implementiert <code>SchM</code> (<code>.c</code>).\n</li><li><code>«includes»</code>: <code>SchM</code> (<code>.c</code>) bindet <code>SchM_cfg</code> (<code>.h</code>) ein.\n</li><li><code>«generates»</code>: Integrator generiert bzw. baut <code>BasicSoftware</code> (<code>.exe</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Zulieferung</strong>: Der BSW-Modullieferant liefert Quellcode bzw. vorkompilierte Binaries (<code>.obj</code>), Konfigurations-Header (<code>&lt;ModulePrefix&gt;_cfg.h</code>) und XML-Beschreibungen (<code>&lt;ModulePrefix&gt;_Description.XML</code>) an den Integrator (<code>«deliveredTo»</code>).\n</li><li><strong>Implementierung</strong>: Der Integrator implementiert den BSW-Scheduler (<code>SchM.c</code>) unter Bezugnahme auf die Modulbeschreibungen und BSW-Artefakte.\n</li><li><strong>Inklusion &amp; Schnittstellen</strong>: <code>SchM.c</code> inkludiert die Konfiguration <code>SchM_cfg.h</code>; modulspezifische Header (<code>SchM_&lt;ModulePrefix&gt;.h</code>, optimierte Varianten) stellen die Scheduler-Schnittstellen für die BSW-Module bereit.\n</li><li><strong>Erzeugung</strong>: Der Integrator erzeugt über Link- und Build-Schritte aus den Modulobjekten und SchM-Quellen das lauffähige Binary <code>BasicSoftware.exe</code> (<code>«generates»</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild verdeutlicht die Integratorperspektive auf die BSW-Scheduler-Generierung und -Kompilierung. In frühen AUTOSAR-Releases (R2.1/R3.0) ist der SchM häufig noch manuell oder halbautomatisch durch den Integrator implementiert bzw. konfiguriert worden. Entwickler müssen sicherstellen, dass die BSW-Modul-Header (<code>&lt;ModulePrefix&gt;_cfg.h</code>) und SchM-Header (<code>SchM_&lt;ModulePrefix&gt;.h</code>) konsistent eingebunden werden und XML-Beschreibungen mit den Binärartefakten (<code>.obj</code>) der Module übereinstimmen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-5ae260ffc63d2a7c", "to": "FIG-9909d30d87148705", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
